#!/usr/bin/env node
'use strict';

/**
 * Validador seguro de branding para las plantillas PDF/ticket de AYSunat.
 * Actualiza colores, logo, datos comerciales, cuentas y pruebas del módulo printing.
 * Ejecutar desde la raíz del proyecto: node update-printing-branding-validation.cjs
 */
const fs = require('node:fs');
const path = require('node:path');
const manifest = JSON.parse(Buffer.from('', 'base64').toString('utf8'));
const root = process.cwd();
for (const [relativePath, contents] of Object.entries(manifest)) {
  const target = path.join(root, relativePath);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, contents, 'utf8');
  console.log(`✓ Actualizado: ${relativePath}`);
}
console.log('\nValidaciones de branding instaladas. Ejecuta npm test y npm run typecheck.');
